<template>
	<view class="mailbox-page">
		<view class="fixed-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar">
				<view class="back-btn" @click="goBack">‹</view>
				<text class="nav-title">我的纸条</text>
				<view class="write-btn" @click="goWrite">写纸条</view>
			</view>
			<view class="mail-tabs">
				<view
					v-for="tab in tabs"
					:key="tab.value"
					class="mail-tab"
					:class="{ active: activeTab === tab.value }"
					@click="switchTab(tab.value)"
				>
					<text>{{ tab.label }}</text>
					<text class="tab-count">{{ getTabCount(tab.value) }}</text>
				</view>
			</view>
		</view>

		<scroll-view
			class="mailbox-scroll"
			scroll-y
			enhanced
			:show-scrollbar="false"
			refresher-enabled
			refresher-background="#fffafd"
			:refresher-triggered="refreshing"
			:style="{ paddingTop: headerHeight + 'px' }"
			@refresherrefresh="refreshMailbox"
		>
			<view v-if="loading && !currentList.length" class="state-box">
				<view class="state-note loading-note">
					<text class="state-title">正在整理纸条</text>
					<view class="load-dots">
						<text></text>
						<text></text>
						<text></text>
					</view>
				</view>
			</view>

			<view v-else-if="!currentList.length" class="state-box">
				<view class="state-note">
					<text class="state-title">{{ emptyTitle }}</text>
					<text class="state-desc">{{ emptyDesc }}</text>
					<view v-if="activeTab === 'sent'" class="state-action" @click="goWrite">写一张</view>
				</view>
			</view>

			<view v-else class="note-list">
				<view
					v-for="item in currentList"
					:key="item.id"
					class="note-card"
					@click="openItem(item)"
				>
					<image class="note-avatar" :src="getItemAvatar(item)" mode="aspectFill" />
					<view class="note-main">
						<view class="note-head">
							<VipName class="note-author" :name="getItemAuthor(item)" :is-member="getItemMember(item)" />
							<text v-if="item.unread" class="note-unread"></text>
							<text class="note-time">{{ getItemTime(item) }}</text>
						</view>
						<text class="note-content">{{ getItemContent(item) }}</text>
					</view>
				</view>
			</view>

			<view class="bottom-safe"></view>
		</scroll-view>

		<view v-if="detailVisible" class="detail-mask" @click="closeDetail">
			<view class="detail-sheet-wrap" @click.stop>
				<view class="detail-tape tape-left"></view>
				<view class="detail-tape tape-right"></view>
				<view class="detail-sheet">
					<view class="detail-head">
						<view class="detail-author">
							<image class="detail-avatar" :src="getItemAvatar(currentDetail || {})" mode="aspectFill" />
							<view class="detail-author-info">
								<VipName class="detail-name" :name="getItemAuthor(currentDetail || {})" :is-member="getItemMember(currentDetail || {})" />
								<text class="detail-meta">{{ getItemTime(currentDetail || {}) }}</text>
							</view>
						</view>
						<view class="detail-close" @click="closeDetail">×</view>
					</view>
					<view class="detail-divider"></view>
					<text class="detail-label">{{ detailTitle }}</text>
					<text class="detail-content">{{ detailContent }}</text>
					<view v-if="detailThread.length" class="thread-list">
						<view v-for="reply in detailThread" :key="reply.id" class="thread-block">
							<view class="thread-item">
								<image class="thread-avatar" :src="getReplyAvatar(reply)" mode="aspectFill" />
								<view class="thread-main">
									<view class="thread-head">
										<VipName class="thread-name" :name="getReplyAuthor(reply)" :is-member="Boolean(reply.author && reply.author.isMember)" />
										<text class="thread-time">{{ reply.time || formatDate(reply.createdAt) }}</text>
									</view>
									<text class="thread-content">{{ reply.content }}</text>
								</view>
							</view>
							<view v-if="reply.adminReply" class="thread-item admin">
								<image class="thread-avatar" :src="getAdminReplyAvatar()" mode="aspectFill" />
								<view class="thread-main">
									<view class="thread-head">
										<VipName class="thread-name" :name="getAdminReplyAuthor()" :is-member="getAdminReplyMember()" />
										<text class="thread-time">{{ reply.adminTime || formatDate(reply.adminRepliedAt) }}</text>
									</view>
									<text class="thread-content">{{ reply.adminReply }}</text>
								</view>
							</view>
						</view>
					</view>
					<view v-else class="thread-empty">还没有收到回复</view>
					<view class="detail-reply-box">
						<textarea
							v-model="detailReplyContent"
							class="detail-reply-input"
							placeholder="继续回复这张小纸条..."
							placeholder-class="detail-reply-placeholder"
							maxlength="300"
							auto-height
						/>
						<view class="detail-reply-foot">
							<text>{{ detailReplyContent.length }} / 300</text>
							<view class="detail-reply-submit" :class="{ disabled: !canSubmitDetailReply }" @click="sendDetailReply">
								{{ detailReplySubmitting ? '发送中...' : '回复' }}
							</view>
						</view>
					</view>
				</view>
			</view>
		</view>

		<SoftToast
			:visible="softToast.visible"
			:message="softToast.message"
			:type="softToast.type"
		/>
		<SuccessFlyModal
			:visible="successFly.visible"
			:label="successFly.label"
			:sublabel="successFly.sublabel"
			@close="handleSuccessFlyClose"
		/>
	</view>
</template>

<script>
import { fetchMyNotes, markNoteRepliesRead, replyNote } from '../../api/note';
import { DEFAULT_AVATAR_URL } from '../../config';
import { showRequestError } from '../../utils/feedback';
import { getCurrentUser } from '../../utils/auth';
import * as profileGuard from '../../utils/profileGuard';
import VipName from '../../components/VipName.vue';
import SoftToast from '../../components/SoftToast.vue';
import SuccessFlyModal from '../../components/SuccessFlyModal.vue';

export default {
	components: { VipName, SoftToast, SuccessFlyModal },
	data() {
		return {
			statusBarHeight: 44,
			headerHeight: 160,
			activeTab: 'sent',
			loading: false,
			refreshing: false,
			detailVisible: false,
			currentDetail: null,
			detailReplyContent: '',
			detailReplySubmitting: false,
			pendingOpenNoteId: '',
			sentItems: [],
			replyItems: [],
			tabs: [
				{ label: '我放飞的', value: 'sent' },
				{ label: '我回复的', value: 'replies' }
			],
			softToast: {
				visible: false,
				message: '',
				type: 'success'
			},
			softToastTimer: null,
			successFly: {
				visible: false,
				label: '',
				sublabel: ''
			}
		};
	},
	computed: {
		currentList() {
			return this.activeTab === 'replies' ? this.replyItems : this.sentItems;
		},
		emptyTitle() {
			return this.activeTab === 'sent' ? '还没有放飞纸条' : '还没有回复过纸条';
		},
		emptyDesc() {
			return this.activeTab === 'sent'
				? '写下一张小纸条，它会被某个同频的人捡起。'
				: '捡起一张纸条并认真回复后，它会出现在这里。';
		},
		detailTitle() {
			return this.activeTab === 'sent' ? '我的小纸条' : 'TA 的小纸条';
		},
		detailContent() {
			if (!this.currentDetail) return '';
			return this.getItemContent(this.currentDetail);
		},
		detailThread() {
			if (!this.currentDetail || !Array.isArray(this.currentDetail.thread)) return [];
			return this.currentDetail.thread;
		},
		canSubmitDetailReply() {
			return !this.detailReplySubmitting && Boolean(this.currentDetail && this.detailReplyContent.trim());
		}
	},
	onLoad(query = {}) {
		this.setHeaderHeight();
		if (query.tab === 'replies') {
			this.activeTab = 'replies';
		}
		this.pendingOpenNoteId = query.noteId || '';
		this.loadMailbox();
	},
	onShow() {
		this.loadMailbox({ silent: true });
	},
	methods: {
		setHeaderHeight() {
			try {
				const info = uni.getSystemInfoSync();
				this.statusBarHeight = info.statusBarHeight || 44;
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.headerHeight = this.statusBarHeight + Math.round(172 * rpxToPx);
			} catch (error) {
				this.headerHeight = 160;
			}
		},
		async loadMailbox(options = {}) {
			if (!options.silent) this.loading = true;
			try {
				const result = await fetchMyNotes();
				this.sentItems = Array.isArray(result && result.sent) ? result.sent : [];
				this.replyItems = Array.isArray(result && result.replies) ? result.replies : [];
				this.openPendingNoteDetail();
			} catch (error) {
				if (!options.silent) showRequestError(error, '纸条加载失败');
			} finally {
				this.loading = false;
				this.refreshing = false;
			}
		},
		refreshMailbox() {
			this.refreshing = true;
			this.loadMailbox({ silent: true });
		},
		switchTab(value) {
			this.activeTab = value;
		},
		openPendingNoteDetail() {
			if (!this.pendingOpenNoteId || this.detailVisible) return;
			const noteId = this.pendingOpenNoteId;
			const sent = this.sentItems.find((item) => item.id === noteId);
			if (sent) {
				this.pendingOpenNoteId = '';
				this.activeTab = 'sent';
				this.openItem(sent);
				return;
			}
			const replied = this.replyItems.find((item) => item.noteId === noteId || (item.note && item.note.id === noteId));
			if (replied) {
				this.pendingOpenNoteId = '';
				this.activeTab = 'replies';
				this.openItem(replied);
			}
		},
		getTabCount(value) {
			return value === 'replies' ? this.replyItems.length : this.sentItems.length;
		},
		getNotePreview(item = {}) {
			if (item.content) return item.content;
			if (item.type === 'voice' || item.audio) return '一段语音纸条';
			if (item.type === 'image' || item.image) return '一张图片纸条';
			return '';
		},
		getItemSource(item = {}) {
			return this.activeTab === 'replies' ? item.note || {} : item;
		},
		getItemAuthor(item = {}) {
			const source = this.getItemSource(item);
			const author = source.author || {};
			return author.nickname || author.stampNo || (this.activeTab === 'sent' ? '我' : '纸条主人');
		},
		getItemAvatar(item = {}) {
			const source = this.getItemSource(item);
			const author = source.author || {};
			return author.avatarUrl || DEFAULT_AVATAR_URL;
		},
		getItemMember(item = {}) {
			const source = this.getItemSource(item);
			return Boolean(source.author && source.author.isMember);
		},
		getItemContent(item = {}) {
			return this.getNotePreview(this.getItemSource(item));
		},
		getItemTime(item = {}) {
			const source = this.getItemSource(item);
			return item.time || source.time || this.formatDate(item.createdAt || source.createdAt);
		},
		getReplyAuthor(reply = {}) {
			const author = reply.author || {};
			return author.nickname || author.stampNo || '同频旅人';
		},
		getReplyAvatar(reply = {}) {
			const author = reply.author || {};
			return author.avatarUrl || DEFAULT_AVATAR_URL;
		},
		getAdminReplySource() {
			if (!this.currentDetail) return {};
			return this.activeTab === 'replies' ? this.currentDetail.note || {} : this.currentDetail;
		},
		getAdminReplyAuthor() {
			const source = this.getAdminReplySource();
			const author = source.author || {};
			return author.nickname || author.stampNo || '纸条主人';
		},
		getAdminReplyAvatar() {
			const source = this.getAdminReplySource();
			const author = source.author || {};
			return author.avatarUrl || DEFAULT_AVATAR_URL;
		},
		getAdminReplyMember() {
			const source = this.getAdminReplySource();
			return Boolean(source.author && source.author.isMember);
		},
		formatDate(value) {
			if (!value) return '';
			const date = new Date(value);
			if (!date.getTime()) return '';
			return `${date.getMonth() + 1}.${date.getDate()}`;
		},
		async openItem(item) {
			this.currentDetail = item;
			this.detailVisible = true;
			this.detailReplyContent = '';
			const replyIds = this.getUnreadReplyIds(item);
			if (!replyIds.length) return;
			this.clearReadState(replyIds);
			try {
				await markNoteRepliesRead(replyIds);
			} catch (error) {
				// The next refresh will restore unread state if marking read failed.
			}
		},
		closeDetail() {
			this.detailVisible = false;
			this.currentDetail = null;
			this.detailReplyContent = '';
			this.detailReplySubmitting = false;
		},
		getCurrentDetailNoteId() {
			if (!this.currentDetail) return '';
			if (this.activeTab === 'replies') {
				return this.currentDetail.noteId || (this.currentDetail.note && this.currentDetail.note.id) || '';
			}
			return this.currentDetail.id || '';
		},
		async sendDetailReply() {
			const noteId = this.getCurrentDetailNoteId();
			const content = this.detailReplyContent.trim();
			if (!noteId || this.detailReplySubmitting) return;
			if (!content) {
				this.showSoftToast('先写一句回复', 'warn');
				return;
			}
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '回复小纸条' }))) return;
			this.detailReplySubmitting = true;
			try {
				const reply = await replyNote(noteId, { content });
				const user = getCurrentUser() || {};
				const nextReply = {
					id: (reply && reply.id) || `local_${Date.now()}`,
					noteId,
					userId: user.id || user.userId || '',
					content,
					createdAt: (reply && reply.createdAt) || new Date().toISOString(),
					time: '刚刚',
					author: {
						nickname: user.nickname || user.name || user.stampNo || '我',
						avatarUrl: user.avatarUrl || user.avatar || DEFAULT_AVATAR_URL,
						stampNo: user.stampNo || ''
					}
				};
				this.currentDetail = {
					...this.currentDetail,
					thread: [...this.detailThread, nextReply]
				};
				this.detailReplyContent = '';
				this.showSuccessFly('回复已送达', '对方会收到你的温暖');
				this.loadMailbox({ silent: true });
			} catch (error) {
				showRequestError(error, '回复失败');
			} finally {
				this.detailReplySubmitting = false;
			}
		},
		getUnreadReplyIds(item = {}) {
			const ids = [];
			(Array.isArray(item.thread) ? item.thread : []).forEach((reply) => {
				if (reply && reply.unread && reply.id) ids.push(reply.id);
			});
			return Array.from(new Set(ids));
		},
		clearReadState(replyIds = []) {
			const idSet = new Set(replyIds);
			const markList = (list = []) => list.map((item) => {
				const thread = (Array.isArray(item.thread) ? item.thread : []).map((reply) => ({
					...reply,
					unread: reply.unread && !idSet.has(reply.id),
					adminReplyReadAt: idSet.has(reply.id) ? (reply.adminReplyReadAt || new Date().toISOString()) : reply.adminReplyReadAt
				}));
				const next = {
					...item,
					unread: thread.some((reply) => reply.unread),
					thread
				};
				if (this.currentDetail && this.currentDetail.id === item.id) {
					this.currentDetail = next;
				}
				return next;
			});
			this.sentItems = markList(this.sentItems);
			this.replyItems = markList(this.replyItems);
		},
		async goWrite() {
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '写小纸条' }))) return;
			try {
				uni.setStorageSync('meetOpenWriteNote', '1');
			} catch (error) {
				// The meet page still opens normally if storage is unavailable.
			}
			uni.switchTab({ url: '/pages/meet/index' });
		},
		goBack() {
			const pages = getCurrentPages();
			if (pages.length > 1) {
				uni.navigateBack();
				return;
			}
			uni.switchTab({ url: '/pages/meet/index' });
		},
		showSoftToast(message, type = 'success', duration = 1800) {
			if (this.softToastTimer) {
				clearTimeout(this.softToastTimer);
				this.softToastTimer = null;
			}
			this.softToast = { visible: true, message: String(message || ''), type };
			this.softToastTimer = setTimeout(() => {
				this.softToast = { ...this.softToast, visible: false };
				this.softToastTimer = null;
			}, duration);
		},
		showSuccessFly(label, sublabel = '') {
			this.successFly = { visible: false, label, sublabel };
			this.$nextTick(() => {
				this.successFly = { visible: true, label, sublabel };
			});
		},
		handleSuccessFlyClose() {
			this.successFly = { ...this.successFly, visible: false };
		}
	}
};
</script>

<style lang="scss" scoped>
.mailbox-page {
	min-height: 100vh;
	background: #fffafd;
	overflow: hidden;
}

.fixed-header {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 10;
	background: rgba(255, 250, 253, 0.96);
	border-bottom: 1rpx solid rgba(238, 232, 242, 0.78);
	backdrop-filter: blur(12rpx);
	-webkit-backdrop-filter: blur(12rpx);
}

.fixed-header::before {
	content: '';
	position: absolute;
	left: 0;
	right: 0;
	top: 0;
	height: 220rpx;
	pointer-events: none;
	background: linear-gradient(135deg, rgba(255, 220, 236, 0.72), rgba(236, 229, 255, 0.76) 54%, rgba(232, 250, 244, 0.58));
	opacity: 0.72;
}

.nav-bar,
.mail-tabs {
	position: relative;
	z-index: 1;
}

.nav-bar {
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 96rpx;
	padding: 0 28rpx;
	box-sizing: border-box;
}

.back-btn,
.write-btn {
	display: flex;
	align-items: center;
	justify-content: center;
	min-width: 86rpx;
	height: 70rpx;
	color: #d4688a;
	font-size: 25rpx;
	font-weight: 700;
}

.back-btn {
	justify-content: flex-start;
	color: #33262e;
	font-size: 54rpx;
	font-weight: 400;
	line-height: 1;
}

.write-btn {
	justify-content: flex-end;
}

.nav-title {
	position: absolute;
	left: 150rpx;
	right: 150rpx;
	text-align: center;
	font-size: 32rpx;
	font-weight: 800;
	color: #2f2432;
}

.mail-tabs {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 12rpx;
	padding: 0 28rpx 22rpx;
	box-sizing: border-box;
}

.mail-tab {
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 8rpx;
	height: 62rpx;
	border-radius: 999rpx;
	background: rgba(255, 255, 255, 0.74);
	border: 1rpx solid rgba(246, 224, 236, 0.9);
	color: #9a7f92;
	font-size: 25rpx;
	font-weight: 700;
}

.mail-tab.active {
	color: #ffffff;
	background: linear-gradient(135deg, #ff8ba7, #d4688a);
	border-color: transparent;
	box-shadow: 0 12rpx 24rpx rgba(212, 104, 138, 0.22);
}

.tab-count {
	font-size: 21rpx;
	opacity: 0.82;
}

.mailbox-scroll {
	height: 100vh;
	box-sizing: border-box;
}

.note-list {
	display: flex;
	flex-direction: column;
	gap: 14rpx;
	padding: 22rpx 30rpx 0;
}

.note-card,
.state-note {
	position: relative;
	border-radius: 8rpx;
	background: rgba(255, 255, 255, 0.92);
	border: 1rpx solid rgba(246, 224, 236, 0.9);
	box-shadow: 0 8rpx 22rpx rgba(84, 54, 78, 0.045);
}

.note-card {
	display: flex;
	align-items: flex-start;
	gap: 18rpx;
	padding: 24rpx 26rpx;
	box-sizing: border-box;
}

.note-card:active {
	transform: scale(0.99);
}

.note-avatar {
	width: 72rpx;
	height: 72rpx;
	border-radius: 50%;
	background: #f7eef5;
	border: 4rpx solid #fff5fa;
	flex-shrink: 0;
}

.note-main {
	flex: 1;
	min-width: 0;
	padding-top: 2rpx;
}

.note-head {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 18rpx;
}

.note-time {
	display: block;
	flex-shrink: 0;
	color: #aaa0b0;
	font-size: 22rpx;
	line-height: 1.5;
}

.note-unread {
	width: 14rpx;
	height: 14rpx;
	border-radius: 50%;
	background: #ff5f8f;
	box-shadow: 0 0 0 6rpx rgba(255, 95, 143, 0.12);
	flex-shrink: 0;
}

.note-content {
	display: -webkit-box;
	margin-top: 10rpx;
	overflow: hidden;
	text-overflow: ellipsis;
	-webkit-box-orient: vertical;
	-webkit-line-clamp: 2;
	line-clamp: 2;
	color: #3e3340;
	font-size: 27rpx;
	line-height: 1.62;
}

.note-author {
	display: block;
	flex: 1;
	min-width: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	color: #352238;
	font-size: 27rpx;
	font-weight: 800;
}

.state-box {
	padding: 70rpx 40rpx 0;
}

.state-note {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	min-height: 310rpx;
	padding: 42rpx 34rpx;
	box-sizing: border-box;
	text-align: center;
}

.state-title,
.state-desc {
	display: block;
}

.state-title {
	color: #3b2f3e;
	font-size: 30rpx;
	font-weight: 800;
}

.state-desc {
	margin-top: 14rpx;
	color: #9c879a;
	font-size: 24rpx;
	line-height: 1.6;
}

.state-action {
